CREATE OR REPLACE VIEW v_active_customers AS
SELECT customer_id, first_name, last_name, email
FROM customer
WHERE active = true;

GRANT SELECT ON v_active_customers TO reporting_role;

CREATE OR REPLACE FUNCTION set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_customer_updated_at
BEFORE UPDATE ON customer
FOR EACH ROW
EXECUTE FUNCTION set_updated_at();

CREATE TABLE event (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    payload     jsonb NOT NULL
);

CREATE INDEX idx_event_payload_gin ON event USING gin (payload jsonb_path_ops);

-- Containment query (uses the GIN index)
SELECT id, payload->>'type' AS type, payload->'user'->>'id' AS user_id
FROM event
WHERE payload @> '{"type": "click", "user": {"country": "US"}}'
ORDER BY occurred_at DESC
LIMIT 100;

-- Group role (no login) for read-only access
CREATE ROLE reporting_ro NOLOGIN;
GRANT USAGE ON SCHEMA public TO reporting_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA public TO reporting_ro;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT ON TABLES TO reporting_ro;

-- Login role that inherits from the group
CREATE ROLE alice LOGIN PASSWORD '...' IN ROLE reporting_ro;

-- Dimension tables (denormalized)
CREATE TABLE dim_customer (
    customer_key   bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_id    bigint UNIQUE NOT NULL,  -- natural key from source
    name           text,
    segment        text,
    effective_from date NOT NULL,
    effective_to   date,
    is_current     boolean NOT NULL DEFAULT true
);

CREATE TABLE dim_date (
    date_key   int PRIMARY KEY,  -- YYYYMMDD
    full_date  date NOT NULL,
    year       int, month int, day int, quarter int, day_of_week int
);

-- Fact table (events/measures)
CREATE TABLE fact_payment (
    payment_key  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    customer_key bigint NOT NULL REFERENCES dim_customer(customer_key),
    date_key     int    NOT NULL REFERENCES dim_date(date_key),
    amount       numeric(10,2) NOT NULL,
    payment_date timestamptz NOT NULL
);

CREATE INDEX ON fact_payment(date_key);
CREATE INDEX ON fact_payment(customer_key);
